import numpy as np
class Tensor:
    def __init__(self, val, children=None):
        self.val=val; self.grad=0; self._backward=lambda:None; self._prev=children or ()
    def __add__(self, other):
        other = other if isinstance(other,Tensor) else Tensor(other)
        out = Tensor(self.val+other.val, (self,other))
        def _bw(): self.grad += out.grad; other.grad += out.grad
        out._backward = _bw; return out
    def __mul__(self, other):
        other = other if isinstance(other,Tensor) else Tensor(other)
        out = Tensor(self.val*other.val, (self,other))
        def _bw(): self.grad += other.val*out.grad; other.grad += self.val*out.grad
        out._backward = _bw; return out
    def sigmoid(self):
        s = 1/(1+np.exp(-self.val))
        out = Tensor(s, (self,))
        def _bw(): self.grad += s*(1-s)*out.grad
        out._backward = _bw; return out
    def backward(self):
        order = []; seen = set()
        def dfs(n):
            if n not in seen: seen.add(n); [dfs(c) for c in n._prev]; order.append(n)
        dfs(self)
        self.grad = 1
        for n in reversed(order): n._backward()

import numpy as np
def rosenbrock(x, y, a=1, b=100):
    return (a-x)**2 + b*(y-x**2)**2
def rosenbrock_grad(x, y, a=1, b=100):
    dx = -2*(a-x) - 4*b*x*(y-x**2)
    dy = 2*b*(y-x**2)
    return np.array([dx, dy])
def sgd(x0, lr=0.001, steps=100):
    x = np.array(x0, dtype=float); hist = [x.copy()]
    for _ in range(steps):
        g = rosenbrock_grad(x[0], x[1])
        x -= lr*g; hist.append(x.copy())
    return {"trajectory": [h.tolist() for h in hist], "final": x.tolist()}
def momentum_sgd(x0, lr=0.001, beta=0.9, steps=100):
    x = np.array(x0, dtype=float); v = np.zeros_like(x); hist = [x.copy()]
    for _ in range(steps):
        g = rosenbrock_grad(x[0], x[1])
        v = beta*v + g; x -= lr*v; hist.append(x.copy())
    return {"trajectory": [h.tolist() for h in hist], "final": x.tolist()}
def adam_optimizer(x0, lr=0.01, steps=100):
    x = np.array(x0, dtype=float); m=v=np.zeros_like(x); t=0; hist=[x.copy()]
    for _ in range(steps):
        t+=1; g=rosenbrock_grad(x[0],x[1])
        m=0.9*m+0.1*g; v=0.999*v+0.001*g**2
        mh=m/(1-0.9**t); vh=v/(1-0.999**t)
        x -= lr*mh/(np.sqrt(vh)+1e-8); hist.append(x.copy())
    return {"trajectory": [h.tolist() for h in hist], "final": x.tolist()}

